import assert from "node:assert/strict";
import { after, before, describe, it } from "node:test";
import { startServer, type Running } from "./helpers/server.ts";

interface Task {
  id: number;
  title: string;
}

interface ApiError {
  error: { code: string; message: string };
}

async function createTask(server: Running, title: string): Promise<Response> {
  return fetch(`${server.baseUrl}/api/tasks`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ title }),
  });
}

async function listTasks(server: Running): Promise<Task[]> {
  const response = await fetch(`${server.baseUrl}/api/tasks`);
  assert.equal(response.status, 200);
  const body = (await response.json()) as { tasks: Task[] };
  return body.tasks;
}

async function assertRejected(server: Running, title: string, message: string): Promise<void> {
  const before = await listTasks(server);

  const response = await createTask(server, title);
  assert.equal(response.status, 400);
  const body = (await response.json()) as ApiError;
  assert.equal(body.error.code, "validation_failed");
  assert.equal(body.error.message, message);

  assert.deepEqual(await listTasks(server), before, "the list is unchanged");
}

describe("SL-004 reject empty and over-long titles", () => {
  let server: Running;

  before(async () => {
    server = await startServer();
  });
  after(async () => {
    await server?.stop();
  });

  describe("AC-1: a title that is empty after trimming", () => {
    it("AC-1: an empty title is rejected with 'A title is required.' and nothing is stored", async () => {
      await assertRejected(server, "", "A title is required.");
    });

    it("AC-1: a title of only spaces is rejected the same way", async () => {
      await assertRejected(server, "     ", "A title is required.");
    });

    it("AC-1: a title of only tabs and line breaks is rejected the same way", async () => {
      await assertRejected(server, "\t\n \r\n", "A title is required.");
    });
  });

  describe("AC-2: a title longer than 500 characters", () => {
    it("AC-2: a 501-character title is rejected with 'too long' and nothing is stored", async () => {
      await assertRejected(
        server,
        "a".repeat(501),
        "The title is too long (maximum 500 characters).",
      );
    });

    it("AC-2: the limit counts the trimmed title, so 501 characters plus outer spaces is still rejected", async () => {
      await assertRejected(
        server,
        `  ${"a".repeat(501)}  `,
        "The title is too long (maximum 500 characters).",
      );
    });

    it("AC-2: a title of exactly 500 characters is accepted", async () => {
      const title = "a".repeat(500);
      const response = await createTask(server, title);
      assert.equal(response.status, 201);
      const { task } = (await response.json()) as { task: Task };
      assert.equal(task.title, title);
      assert.ok((await listTasks(server)).some((t) => t.id === task.id));
    });

    it("AC-2: 500 characters with outer spaces is accepted, because the spaces are not counted", async () => {
      const title = "b".repeat(500);
      const response = await createTask(server, `   ${title}   `);
      assert.equal(response.status, 201);
      const { task } = (await response.json()) as { task: Task };
      assert.equal(task.title, title);
    });
  });

  describe("AC-1 and AC-2: after a rejection the owner can correct the title", () => {
    it("AC-1: a valid title submitted after a rejected one is added normally", async () => {
      const rejected = await createTask(server, "   ");
      assert.equal(rejected.status, 400);

      const accepted = await createTask(server, "Call the dentist");
      assert.equal(accepted.status, 201);
      const titles = (await listTasks(server)).map((t) => t.title);
      assert.equal(titles.filter((t) => t === "Call the dentist").length, 1);
    });
  });

  describe("AC-1 and AC-2: the page shows the reason", () => {
    let html: string;
    let script: string;

    before(async () => {
      html = await (await fetch(`${server.baseUrl}/`)).text();
      script = await (await fetch(`${server.baseUrl}/app.js`)).text();
    });

    it("AC-1: the page has a message area with role=alert and id form-message", () => {
      assert.match(html, /<[a-z]+(?=[^>]*id=["']form-message["'])(?=[^>]*role=["']alert["'])/);
    });

    it("AC-1: the page script reads the API error message and puts it in form-message", () => {
      assert.match(script, /form-message/);
      assert.match(script, /error\.message/);
      assert.doesNotMatch(script, /innerHTML/);
    });
  });
});
